using UnityEngine;

namespace RoguelikePool
{
    /// <summary>
    /// The cue (Cue prefab, generated by Tools > Roguelike Pool). The root (CueRoot) sits on the cue ball
    /// center and turns with the aim: its +X axis points in the shot direction. The child <see cref="stick"/>
    /// carries the sprite, whose pivot is the tip; it slides back along -X by the tip distance (resting gap
    /// plus the power pull-back), so the recoil never changes the rotation center.
    /// The sprite is drawn vertically with the tip at the top: <see cref="spriteRotationOffset"/> (-90°) turns
    /// its tip toward +X. <see cref="CueController"/> drives it through <see cref="Pose"/>.
    /// </summary>
    public class CueStick : MonoBehaviour
    {
        [Tooltip("Enfant qui porte le sprite de la queue (pivot à la pointe).")]
        public Transform stick;
        [Tooltip("Rotation ajoutée au sprite pour que sa pointe regarde dans la direction du tir (sprite vertical, pointe en haut : -90).")]
        public float spriteRotationOffset = -90f;

        SpriteRenderer stickRenderer;

        /// <summary>Length of the drawn cue in world units, tip to butt (from the stick sprite).</summary>
        public float Length
        {
            get
            {
                if (stickRenderer == null && stick != null) stickRenderer = stick.GetComponentInChildren<SpriteRenderer>();
                if (stickRenderer == null || stickRenderer.sprite == null) return 0f;
                var s = stickRenderer.sprite;
                return s.rect.height / s.pixelsPerUnit * stickRenderer.transform.lossyScale.y;
            }
        }

        /// <summary>Places the cue: root on the ball, pointing along <paramref name="direction"/>, tip <paramref name="tipDistance"/> behind the ball center.</summary>
        public void Pose(Vector2 ballCenter, Vector2 direction, float tipDistance)
        {
            transform.SetPositionAndRotation(ballCenter, Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg));
            if (stick == null) return;
            stick.localPosition = new Vector3(-tipDistance, 0f, 0f);
            stick.localRotation = Quaternion.Euler(0f, 0f, spriteRotationOffset);
        }
    }
}
